import { test, expect } from '@playwright/test';

test.describe('Search Bar Expansion on Mobile Focus', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should expand search bar on focus on mobile viewport', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 862 });

    const searchInput = page.getByPlaceholder('Search...');
    await expect(searchInput).toBeVisible();

    const searchContainer = page.locator('[data-testid="search-container"]');
    await expect(searchContainer).toBeVisible();

    const expandButton = page.getByRole('button', { name: /expand/i });
    await expect(expandButton).not.toBeVisible();

    await searchInput.click();

    await expect(expandButton).toBeVisible();

    const expandedContainer = page.locator('[data-testid="search-container-expanded"]');
    await expect(expandedContainer).toBeVisible();

    const searchResults = page.locator('[data-testid="search-results"]');
    await expect(searchResults).toBeVisible();

    const searchInputValue = await searchInput.inputValue();
    expect(searchInputValue).toBe('');
  });

  test('should collapse search bar when focus is lost on mobile viewport', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 860 });

    const searchInput = page.getByPlaceholder('Search...');
    await expect(searchInput).toBeVisible();

    const searchContainer = page.locator('[data-testid="search-container"]');
    await expect(searchContainer).toBeVisible();

    const expandButton = page.getByRole('button', { name: /expand/i });
    await expect(expandButton).not.toBeVisible();

    await searchInput.click();

    await expect(expandButton).toBeVisible();

    const expandedContainer = page.locator('[data-testid="search-container-expanded"]');
    await expect(expandedContainer).toBeVisible();

    const searchResults = page.locator('[data-testid="search-results"]');
    await expect(searchResults).toBeVisible();

    await page.mouse.down({ x: 10, y: 10 });
    await page.mouse.move({ x: 10, y: 10 });
    await page.mouse.up();

    await expect(expandedContainer).not.toBeVisible();

    const collapsedContainer = page.locator('[data-testid="search-container"]');
    await expect(collapsedContainer).toBeVisible();

    const searchInputValue = await searchInput.inputValue();
    expect(searchInputValue).toBe('');
  });
});
